const tabId = 1148881640;

const extractedPros = await browserjs(tabId, () => {
  // Let's inspect all links that point to pro profiles or instant-results
  // In the snapshot, we saw links like:
  // "Unlimited Electrical Solutions Group inc. Top Pro Excellent 4.9..."
  // Let's find all such links/cards
  const proLinks = Array.from(document.querySelectorAll('a')).filter(a => {
    return a.textContent.includes('View profile') || 
           a.href.includes('/profile/services/') || 
           a.href.includes('/instant-results/service/');
